    private static readonly byte[] EnglishWordsUtf8 = Encoding.UTF8.GetBytes(EnglishWords);

    public static string GenerateRandomString()
    {
        (int offset, int length) = GenerateRandomRange();
        return EnglishWords.AsSpan(offset, length).ToString();
    }

    private static (int Offset, int Length) GenerateRandomRange()
    {
        var offset = Random.Shared.Next(EnglishWords.Length - Max);
        if (EnglishWords[offset] == ' ')
        {
            offset++;
        }

        var length = Random.Shared.Next(Min, Max);
        return (offset, length);
    }
